    /**
     * @method renderSwiperHtml
     * @description 生成图片轮播的HTML内容。
     * @param {number} id - 产品ID。
     * @param {string} title - 产品标题。
     * @param {Array<string>} images - 图片URL数组。
     * @returns {string} 图片轮播的HTML字符串。
     */
    renderSwiperHtml(id, title, images) {
        let slideHtml = ''
        images.forEach((item) => {
            slideHtml += `
                <div class="swiper-slide">
                    <div class="image">
                        <img src="${item}" alt="${title}">
                    </div>
                </div>
            `
        })
        let html = `
            <div thumbsSlider="" class="swiper main-swiper mySwiper-${id}">
                <div class="swiper-wrapper">
                    ${slideHtml}
                </div>
                 <div class="swiper-button swiper-button-next swiper-button-next-${id}"></div>
                <div class="swiper-button swiper-button-prev swiper-button-prev-${id}"></div>
                <div class="swiper-pagination swiper-pagination-${id}"></div>
            </div>
            <div class="swiper sub-swiper swiper-${id}">
                <div class="swiper-wrapper">
                    ${slideHtml}
                </div>
            </div>
        `
        return html
    }

    /**
     * @method createSwiper
     * @description 初始化Swiper轮播实例。
     * @param {Array<object>} list - 包含产品信息的数组。
     */
    createSwiper(list) {
        const _this = this
        list.forEach((item) => {
            const { id } = item
            let swiper = null
            if (!isLessThan1024Screen) {
                swiper = new Swiper(`.swiper-${id}`, {
                    spaceBetween: 10,
                    slidesPerView: 6,
                    freeMode: true,
                    watchSlidesProgress: true,
                })
            }
            const swiper2 = new Swiper(`.mySwiper-${id}`, {
                spaceBetween: 10,
                loop: true,
                navigation: {
                    nextEl: `.swiper-button-next-${id}`,
                    prevEl: `.swiper-button-prev-${id}`,
                },
                ...(isLessThan1024Screen ? {
                    pagination: {
                        el: `.swiper-pagination-${id}`,
                    },
                } : {
                    thumbs: {
                        swiper: swiper,
                    },
                })
            })
        })
    }
    /**
     * @method renderDiscountHtml
     * @description 生成弹窗折扣信息的HTML内容。
     * @param {Array<object>} discountList - 折扣列表数组。
     * @returns {string} 折扣信息的HTML字符串。
     */
    renderDiscountHtml(discountList) {
        let html = ''
        discountList.forEach((item, index) => {
            let text = ''
            if (index !== discountList.length - 1) {
                text += `${item.quantity} - ${discountList[index + 1].quantity - 1} ${this.text.unit} `
            } else {
                text += `${item.quantity} ${this.text.unit} ${this.text.more}`
            }
            html += `
                <div class="discount-item">
                    <span class="info">
                        ${text}
                    </span>
                    <div class="discount">
                        <div class="each">${item.formatPrice} ${this.text.each}</div>
                        <div class="off">${item.value}% ${this.text.off}</div>
                    </div>
                </div>
            `
        })
        return html
    }
