    /**
     * @method handleQuantityInput
     * @description 处理数量输入事件，计算产品总价和格式化价格。
     * @param {number} id - 产品ID。
     * @param {number} quantity - 输入的数量。
     */
    handleQuantityInput(id, quantity) {
        const product = this.data.modalListProduct.find((item) => item.id === id)
        const { discountList, price } = product
        const values = discountList.map(item => item.quantity) || []
        let index = -1
        values.forEach((value, j) => {
            if(quantity >= value) {
                index = j
            }
        })
        if (index !== -1) {
            product.totalPrice = new Decimal(quantity).mul(product.discountList[index].price).toNumber()
        } else {
            product.totalPrice = new Decimal(quantity).mul(price).toNumber()
        }

        product.subTotalPrice = new Decimal(quantity).mul(price).toNumber()
        product.quantity = quantity
        product.totalPriceFormat = formatMoney(Math.ceil(product.totalPrice), pageInfo?.currency?.money_format)
        product.subTotalPriceFormat = formatMoney(Math.ceil(product.subTotalPrice), pageInfo?.currency?.money_format)
        $(`.item-total-price[data-${id}]`).html(`
            ${this.text.subTotal}
            <span class="totle-price">${product.totalPriceFormat}</span>
            <span  class="origin-price">${ product.subTotalPriceFormat}</span>
        `)
    }

    /**
     * @method handleBuyItNow
     * @description 处理立即购买事件，创建购物车并跳转到结账页面。
     * @param {object} dom - 触发事件的DOM元素。
     */
    async handleBuyItNow(dom) {
        dom.addClass('btn--loading')
        const params = this.data.modalListProduct.map(item => ({
            id: item.id,
            quantity: item.quantity,
            properties: {
                Action: 'Bulk-Program'
            },
        }))

        try {
            const checkoutUrl = await createCartAndCheckout(params)
            if (checkoutUrl) {
                window.location.href = checkoutUrl
                const gaParams = {
                    modules: this.data.module,
                    position: this.data.modalListProduct.map(item => item.title).join(','),
                    button_name: dom.text(),
                    type: "bulk_modal"
                }
                gaPushDataLayer('bulk_program_user_clicks', gaParams)
            }
        } catch (error) {
            let str = '/cart/'
            const properties = window.btoa(unescape(encodeURIComponent(JSON.stringify({
                Action: 'Bulk-Program'
            }))))
            this.data.modalListProduct.forEach(item => {
                str += `${item.id}:${item.quantity},`
            })
            str = `${str.substring(0,str.length -1)}?traffic_source=buy_now&properties=${properties}`
            window.location.href = str
        } finally{
            dom.removeClass('btn--loading')
        }
    }

    /**
     * @method handleCheck
     * @description 校验表单输入。
     * @param {object} params - 包含表单数据的对象。
     * @returns {boolean} 如果校验失败返回true，否则返回false。
     */
    handleCheck(params) {
        let isCheck = false
        const formError = this.text.error
        try {
            Object.keys(params).forEach((key) => {
                if (key !== 'phone') {
                    const val = params[key].trim()
                    if (val == '' || (val.length > 255)) {
                        pushErrorMessage(`${formError[key]}`)
                        throw new Error()
                    }
                }
            })
        } catch (error) {
            return isCheck = true
        }

        if (!verifyEmail(params.email)) {
            pushErrorMessage(`${formError.email}`)
            return isCheck = true
        }

        if (params.phone && (params.phone.trim().length < 6 || params.phone.trim().length > 20)) {
            pushErrorMessage(`${formError.phone}`)
            return isCheck = true
        }

        return isCheck
    }

    /**
     * @method handleDownloadPriceList
     * @description 处理下载价格清单事件，包括表单校验和文件下载。
     * @param {HTMLElement} el - 触发事件的DOM元素。
     */
    async handleDownloadPriceList(el) {
        const params = {
            first: $('.download-price-list-modal #first').val(),
            last: $('.download-price-list-modal #last').val(),
            email: $('.download-price-list-modal #email').val(),
            phone: $('.download-price-list-modal #phone').val(),
            company: $('.download-price-list-modal #company').val(),
            industry: $('.download-price-list-modal #industry').val(),
        }
        const flag = this.handleCheck(params)
        if (flag) {
            return
        }
        el.classList.add('btn--loading')
        const skus = this.data.modalListProduct.map(item => {
            const {sku, title, barcode, quantity, totalPrice, totalPriceFormat } = item
            return {
                sku,
                title,
                quantity,
                upc: barcode || '',
                unitCost: formatMoney(totalPrice / quantity, pageInfo?.currency?.money_format),
                total: totalPriceFormat
            }
        })
        const form = {
            ...params,
            skus
        }
        try {
            const res = await downloadBatchPurchaseExcal(form)
            if (res.type === 'application/json') {
                res.text().then(text => {
                    pushErrorMessage(JSON.parse(text).message)
                })
            } else {
                const aLink = document.createElement('a')
                let blob = new Blob([res], {
                    type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
                })
                aLink.href = URL.createObjectURL(blob)
                let name = `${this.text.downloadName} ${form.first} ${form.last}`
                aLink.setAttribute('download', name.replace(/\./g, '-'))
                document.body.appendChild(aLink)
                aLink.click()
                document.body.removeChild(aLink)
                if (this.text.downloadSuccess) {
                    pushSuccessMessage(this.text.downloadSuccess)
                }
                this.handleClosePriceListModal()
                const gaParams = {
                    module: this.data.module,
                    position: this.data.modalListProduct.map(item => `${item.title} x ${item.quantity}`).join(','),
                    button_name: $(el).text(),
                    type: "confirmation_modal"
                }
                gaPushDataLayer('bulk_program_user_clicks', gaParams)
            }
        } catch (err) {
            pushErrorMessage(err.message)
        } finally {
            el.classList.remove('btn--loading')
        }
    }

