    /**
     * @method handleViewQuote
     * @description 处理查看报价事件，过滤并处理定制产品数据。
     * @param {HTMLElement} el - 触发事件的DOM元素。
     */
    async handleViewQuote(el) {
        el.classList.add('btn--loading')
        const _this = this
        try {
            const filteredData = this.data.tailorSelectData.filter(item => item.val !== null);
            // 使用Map去重,以val为key
            const uniqueMap = new Map();
            filteredData.forEach(item => {
                if (!uniqueMap.has(item.val)) {
                    const product = this.data.products.find(product => product.id === item.val)
                    uniqueMap.set(item.val, { ...product, ...{
                        quantity: item.quantity
                    }});
                }
            });
            const finallyData = Array.from(uniqueMap.values());
            if (!finallyData.length) {
                pushErrorMessage(_this.text.tailor.tip)
                return
            }
            if (finallyData.length === 1 && finallyData[0].quantity == 0) {
                pushErrorMessage(_this.text.tailor.quantityTip)
                return
            }
            this.handleQuoteModal(finallyData, el)
        } catch (error) {
            console.log(error)
        } finally {
            el.classList.remove('btn--loading')
        }
    }

    /**
     * @method handleQuoteModal
     * @description 处理报价模态框，计算折扣。
     * @param {Array<object>} list - 产品列表。
     */
    async handleQuoteModal(list = [], el) {
        const _this = this
        _this.data.modalListProduct = []
        for (const item of list) {
            const it = await _this.handleSelectProduct(item)
            _this.data.modalListProduct.push(it)
        }
        _this.calcTotal(true)
        const { module } = el.dataset
        const gaParams = {
            module,
            position: this.data.modalListProduct.map(item => `${item.title} x ${item.quantity}`).join(','),
            button_name: el.textContent,
            type: 'main_page'
        }
        gaPushDataLayer('bulk_program_user_clicks', gaParams)
    }
